INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Pudge le Maladroit', 'Monstres légendaires · Moyenne', 'Ogre stupide légendaire. Exemple du livre : pour un groupe de niveau 2 de 4 héros, il a 112 PV (et 28 PV de plus pour son Baroud d''honneur). En sang, Pudge se met en colère et la taille de son dé augmente, ce qui accroît ses dégâts et réduit ses chances de rater. Pour son Baroud d''honneur, il devient bien plus dangereux, se déplaçant et utilisant sa grosse attaque à chaque tour.', '["Monstres légendaires","Légendaire","Niv. 2"]', 'GM''s Guide', NULL, '{"level":"2","size":"medium","minion":false,"legendary":true,"hp":28,"hpPerHero":true,"armor":null,"speed":null,"saves":"FOR+, INT–","abilities":[],"attacks":[{"name":"Avance et cogne","dice":"1d8","bonus":0,"noCrit":false,"text":"Déplacement de 8, attaque pour 1d8. Si dégâts, à terre."},{"name":"Attrape et lance","dice":"1d8","bonus":0,"noCrit":false,"text":"Si dégâts, (Allonge 6) le lance sur une autre cible : les deux subissent encore 1d8 dégâts et tombent à terre."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, choisissez une option (alterner recommandé) : Avance et cogne ou Attrape et lance."},{"title":"En sang : Piétinement sismique !","text":"Les héros tombent à terre sur un jet de sauvegarde de FOR DD 12 raté."},{"title":"Baroud d''honneur","text":"Pudge regagne 7 PV par héros et lance des d12 pour chaque attaque."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Pudge le Maladroit' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Kelebek, entomancien', 'Monstres légendaires · Moyenne', 'Druide insecte légendaire, en duo avec son familier puant Poppy (Kelebek et Poppy).', '["Monstres légendaires","Légendaire","Niv. 3"]', 'GM''s Guide', NULL, '{"level":"3","size":"medium","minion":false,"legendary":true,"hp":20,"hpPerHero":true,"armor":null,"speed":null,"saves":"INT+, VOL+","abilities":[],"attacks":[{"name":"Fouet de liane","dice":"2d6","bonus":0,"noCrit":false,"text":"Déplacement de 6, puis 2d6. Si dégâts, déplace la cible vers une case inoccupée à Allonge 6."}],"sections":[{"title":"Duo légendaire","text":"Après le tour de chaque héros, choisissez Kelebek OU Poppy pour agir (alterner recommandé)."},{"title":"En sang","text":"Quand Kelebek est en sang, Poppy s''interpose toujours pour lui. Les deux lancent 3d6 à la place."},{"title":"Baroud d''honneur : Gaz nocif","text":"Quand Poppy meurt, tous les héros ont au maximum 2 actions par tour."}]}'
