WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Nalzar, superprédatrice' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Florindris, fléau de la forêt', 'Monstres légendaires · Grande', 'Grand dragon floral légendaire.', '["Monstres légendaires","Légendaire","Niv. 7"]', 'GM''s Guide', NULL, '{"level":"7","size":"large","minion":false,"legendary":true,"hp":64,"hpPerHero":true,"armor":null,"speed":null,"saves":"TOUTES+","abilities":[{"name":"Aura de vent","text":"Les attaques à distance contre vous ont le désavantage. À la fin de votre tour, repoussez les créatures adjacentes de 2 cases."},{"name":"Flétrissure","text":"Résistant aux dégâts nécrotiques, mais ils suppriment Aura de vent jusqu''à la fin du tour du héros suivant."},{"name":"Bourrasque","text":"(Allonge 8) Déplace une cible de 1d10 cases."},{"name":"Épine-fléau","text":"Subit 2 dégâts pour chaque case de déplacement forcé. Les soins mettent fin à cet effet."}],"attacks":[{"name":"Lacérer","dice":"1d10","bonus":10,"noCrit":false,"text":"Vole de 10. (Allonge 2, jusqu''à 2 cibles) En cas de coup au but, gagne Épine-fléau."},{"name":"Tempête de pétales","dice":"2d10","bonus":10,"noCrit":true,"text":"En sang uniquement. (1 utilisation, Allonge 8, zone) Moitié sur un jet de sauvegarde de DEX DD 13 réussi."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, choisissez une option (alterner recommandé) : Bourrasque ou Lacérer."},{"title":"En sang","text":"Les ennemis à Allonge 12 gagnent Épine-fléau. Gagne : **Tempête de pétales.** (1 utilisation, Allonge 8, zone) 2d10+10, moitié sur un jet de sauvegarde de DEX DD 13 réussi."},{"title":"Baroud d''honneur","text":"Florindris regagne 23 PV par héros, et Aura de vent et Bourrasque déplacent les créatures deux fois plus loin."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Florindris, fléau de la forêt' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Général Cœur-de-Flamme', 'Monstres légendaires · Énorme', 'Énorme titan de flammes légendaire.', '["Monstres légendaires","Légendaire","Niv. 8"]', 'GM''s Guide', NULL, '{"level":"8","size":"huge","minion":false,"legendary":true,"hp":64,"hpPerHero":true,"armor":"medium","speed":null,"saves":"FOR++, VOL+","abilities":[{"name":"Armure de cendres","text":"Résistant au feu. Quand il subit des dégâts, inflige 5 dégâts de feu à toutes les créatures adjacentes."},{"name":"Flamme éteinte","text":"Les critiques de glace ou radiants éteignent toutes les zones enflammées par Fureur en fusion et suppriment Armure de cendres jusqu''à la fin du tour du héros suivant."}],"attacks":[{"name":"Taille infernale","dice":"2d10","bonus":10,"noCrit":false,"text":"Déplacement de 6, puis frappe une zone carrée de 3×2. Dégâts de feu."},{"name":"Fureur en fusion","dice":"2d10","bonus":10,"noCrit":false,"text":"Lance une boule de feu en fusion sur le héros le plus éloigné qui n''est pas déjà dans les flammes, enflammant une zone carrée de 2×2. Les créatures qui s''y trouvent subissent les dégâts, puis 10 dégâts de plus à la fin de chacun de leurs tours si elles restent dans la zone."},{"name":"Embrasement (Flammèche)","dice":"1d10","bonus":0,"noCrit":true,"text":"Attaque d''un sbire Flammèche élémentaire. (Allonge 1, zone) Suit les règles des sbires."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, choisissez une option (alterner recommandé) : Taille infernale ou Fureur en fusion."},{"title":"En sang : Engeance de flammes","text":"Chaque Fureur en fusion fait apparaître un sbire Flammèche élémentaire."},{"title":"Flammèche élémentaire (sbire)","text":"Suit les règles des sbires.\n**Embrasement.** (Allonge 1, zone) 1d10.\n**Explosion.** À sa mort, (Allonge 1, zone) 1d10."},{"title":"Baroud d''honneur","text":"Cœur-de-Flamme regagne 19 PV par héros, ses attaques passent à une zone de 3×3. Il fait apparaître une Flammèche à chacun de ses tours."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Général Cœur-de-Flamme' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Vael, nécromancien immortel', 'Monstres légendaires · Moyenne', 'Sommité de la malveillance légendaire.', '["Monstres légendaires","Légendaire","Niv. 9"]', 'GM''s Guide', NULL, '{"level":"9","size":"medium","minion":false,"legendary":true,"hp":64,"hpPerHero":true,"armor":null,"speed":null,"saves":"INT++, VOL++","abilities":[{"name":"Protégez le maître !","text":"Chaque fois que Vael devrait rater un jet de sauvegarde ou subir 20 dégâts ou plus, il peut sacrifier à la place son esprit lié, Fléau."},{"name":"Rappeler Fléau","text":"(1/round) Déplacement de 6 et invoque de nouveau Fléau."}],"attacks":[{"name":"Fléau (esprit lié)","dice":"1d12","bonus":6,"noCrit":false,"text":"Fléau attaque après le tour de chaque héros, avant le choix de Vael."},{"name":"FUNESTE","dice":"2d12","bonus":20,"noCrit":true,"text":"(Portée 12, cible indemne) Jet de sauvegarde de VOL DD 14 ou dégâts. Moitié en cas de réussite."},{"name":"Réprimande de l''arpenteur du voile","dice":"2d12","bonus":6,"noCrit":false,"text":"(Portée 8) Dégâts doublés contre ceux qui sont derrière un abri. (1/round) Vous pouvez échanger votre place avec eux."},{"name":"Tranchant de la cruauté","dice":"1d4","bonus":2,"noCrit":false,"text":"En cas de coup au but, jet de sauvegarde de VOL DD 14 ou étourdi et effrayé. Puis déplacement de 6."},{"name":"Esprit vengeur","dice":"1d12","bonus":6,"noCrit":false,"text":"Baroud d''honneur uniquement. (Allonge 3, zone) À la fin de chacun des tours de Vael."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, Fléau attaque pour 1d12+6, puis Vael choisit une option : FUNESTE, Réprimande de l''arpenteur du voile, Tranchant de la cruauté ou Rappeler Fléau."},{"title":"En sang : Bouclier de cruauté","text":"(Réaction, 1 utilisation) Si Vael devait subir des dégâts, il peut à la place renvoyer autant de dégâts radiants à l''attaquant."},{"title":"Baroud d''honneur : LA MORT, UNE VIEILLE AMIE","text":"Vael regagne 24 PV par héros. Le héros qui l''a blessé le plus récemment tombe à 0 PV, et Fléau est sacrifié en Esprit vengeur qui ne peut plus être rappelé : (Allonge 3, zone) 1d12+6 à la fin de chacun des tours de Vael."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Vael, nécromancien immortel' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Titan des bois profonds', 'Monstres légendaires · Gigantesque', 'Squelette gigantesque légendaire.', '["Monstres légendaires","Légendaire","Niv. 10"]', 'GM''s Guide', NULL, '{"level":"10","size":"gargantuan","minion":false,"legendary":true,"hp":64,"hpPerHero":true,"armor":"heavy","speed":null,"saves":"FOR+++","abilities":[{"name":"Légions éclatées","text":"Les dégâts contondants ou tout critique font éclater des os qui s''animent et forment un sbire squelette (taille : d10)."},{"name":"Os friables","text":"Résistant au perforant, vulnérable au contondant."},{"name":"Appel funeste","text":"Les 2 héros les plus éloignés font un jet de sauvegarde de VOL DD 16 ou sont déplacés adjacents au Titan (désavantage si un squelette leur est adjacent)."}],"attacks":[{"name":"Frappe dévastatrice","dice":"1d4","bonus":30,"noCrit":false,"text":"(Allonge 4) En cas de coup au but, repoussé de 6."},{"name":"Piétinement écrasant","dice":"1d4","bonus":20,"noCrit":false,"text":"Déplacement de 10. Jusqu''à 2 cibles sur le trajet. En cas de coup au but, à terre."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, choisissez 1 option (alterner recommandé) : Frappe dévastatrice, Piétinement écrasant ou Appel funeste."},{"title":"Baroud d''honneur : Légion brisée","text":"À 0 PV, le Titan s''effondre en 4 sbires squelettes par héros (taille : d10). S''il en reste, ils se réassemblent en Titan le soir suivant."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Titan des bois profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Ul''vek, despote psionique', 'Monstres légendaires · Moyenne', 'Aberration mangeuse de cerveaux légendaire.', '["Monstres légendaires","Légendaire","Niv. 11"]', 'GM''s Guide', NULL, '{"level":"11","size":"medium","minion":false,"legendary":true,"hp":84,"hpPerHero":true,"armor":null,"speed":null,"saves":"INT++, VOL++","abilities":[{"name":"Bouclier mental","text":"Chaque fois qu''Ul''vek devrait rater un jet de sauvegarde ou subir plus de 30 dégâts alors qu''il a des créatures dominées, il peut éviter l''attaque à la place, mais toutes les créatures dominées reprennent leurs esprits."},{"name":"Dominé","text":"Vos jets sont désavantagés. Ul''vek dépense votre première action à chacun de vos tours : se déplacer, faire une attaque armée ou lancer un tour de magie. Les dégâts y mettent fin."},{"name":"Contrôle","text":"Se téléporte de 8. (Allonge 8) Jet de sauvegarde de FOR DD 15 : force un ennemi à dépenser une action pour se déplacer, faire une attaque armée ou lancer un tour de magie. En cas de réussite, il se déplace deux fois moins loin ou attaque avec désavantage."}],"attacks":[{"name":"Domination","dice":"2d12","bonus":0,"noCrit":true,"text":"(S''il n''y a aucune créature dominée) Choisissez la moitié des héros : ils subissent 2d12 dégâts psychiques (ignorant la Défense). Jet de sauvegarde de VOL DD 15 ou dominés en plus."},{"name":"Dévorer","dice":"6d12","bonus":0,"noCrit":true,"text":"(créature dominée) Jet de sauvegarde de DEX DD 15 ou dégâts et agrippé (évasion DD 15), moitié en cas de réussite. Impossible de se défendre ou de s''interposer."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, choisissez une option (alterner recommandé) : Domination, Dévorer ou Contrôle."},{"title":"En sang","text":"Gagne : **Déplacement illusoire** (1 utilisation). Réaction (quand il est attaqué) : échange sa place avec une créature dominée, qui devient la nouvelle cible de l''attaque."},{"title":"Baroud d''honneur : DOMINATION !","text":"Ul''vek regagne 30 PV par héros, et chaque héros fait un jet de sauvegarde de VOL DD 15 ou devient dominé. Dominé ne prend plus fin quand on subit des dégâts."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Ul''vek, despote psionique' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Dravok, tyran omnivoyant', 'Monstres légendaires · Grande', 'Grande aberration légendaire, tout en DENTS et en YEUX.', '["Monstres légendaires","Légendaire","Niv. 12"]', 'GM''s Guide', NULL, '{"level":"12","size":"large","minion":false,"legendary":true,"hp":90,"hpPerHero":true,"armor":null,"speed":null,"saves":"INT++, VOL++","abilities":[{"name":"Mes plans, PARFAITS !","text":"Les attaques contre Dravok sont désavantagées, et Dravok fait tous ses jets de sauvegarde avec +1 avantage."},{"name":"Faiblesse","text":"Subir 20 dégâts perforants ou tranchants ou plus en une fois : les plans de Dravok sont IMPARFAITS ! (jusqu''à la fin du tour du héros suivant)."},{"name":"Rayon 5 : Rayon de charme","text":"Dépense 3 actions d''un ennemi (vous ne pouvez dépenser aucune ressource limitée ; il regagne ensuite les actions dépensées)."}],"attacks":[{"name":"Gueule terrible","dice":"4d4","bonus":0,"noCrit":false,"text":"+10 dégâts pour CHAQUE 4 obtenu."},{"name":"Rayon 1 : Rayon de distorsion","dice":"2d6","bonus":10,"noCrit":false,"text":"(Portée 10) Échange sa place avec la cible et la met à terre."},{"name":"Rayon 2 : Rayon de pétrification","dice":"2d6","bonus":10,"noCrit":false,"text":"(Portée 10) Étourdi de façon permanente (cumulable, les soins y mettent fin ; 3 cumuls : pétrifié)."},{"name":"Rayon 3 : Rayon de terreur","dice":"2d6","bonus":10,"noCrit":false,"text":"(Portée 10) Dégâts psychiques et TERRIFIÉ : effrayé, et vos cris donnent le désavantage à vos alliés à Allonge 6 sur leurs jets. Prend fin quand les plans de Dravok sont IMPARFAITS."},{"name":"Rayon 4 : Rayon gravitationnel","dice":"2d6","bonus":0,"noCrit":false,"text":"(Portée 10) Déplace la cible d''autant de cases. Le déplacement forcé inflige +5 dégâts au lieu de lancer des dés supplémentaires."},{"name":"Rayon 6 : Rayon de mort","dice":"d66","bonus":0,"noCrit":false,"text":"(Portée 10) La cible gagne 1 Blessure."},{"name":"Rayon de dévastation","dice":"d66","bonus":0,"noCrit":false,"text":"Baroud d''honneur uniquement. (1 utilisation, Ligne 10×2, zone) Gain d''1 Blessure."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, se déplace de 6 puis utilise soit un Rayon oculaire (Portée 10 ; au choix, dans l''ordre ou au hasard), soit Gueule terrible (4d4, +10 dégâts pour CHAQUE 4 obtenu).\n1. **Rayon de distorsion.** 2d6+10. Échange sa place avec la cible et la met à terre.\n2. **Rayon de pétrification.** 2d6+10. Étourdi de façon permanente (cumulable, les soins y mettent fin ; 3 cumuls : pétrifié).\n3. **Rayon de terreur.** 2d6+10 dégâts psychiques et TERRIFIÉ : effrayé, et vos cris donnent le désavantage à vos alliés à Allonge 6 sur leurs jets. Prend fin quand les plans de Dravok sont IMPARFAITS.\n4. **Rayon gravitationnel.** 2d6, déplace la cible d''autant de cases. Le déplacement forcé inflige +5 dégâts au lieu de lancer des dés supplémentaires.\n5. **Rayon de charme.** Dépense 3 actions d''un ennemi (vous ne pouvez dépenser aucune ressource limitée ; il regagne ensuite les actions dépensées).\n6. **Rayon de mort.** d66, gain d''1 Blessure."},{"title":"En sang : Poussière !","text":"Rayon de pétrification sur chaque ennemi. Le DD de ses sauvegardes passe à 18."},{"title":"Baroud d''honneur","text":"Dravok regagne 32 PV par héros. À chaque tour, il utilise Rayon de distorsion puis une autre attaque. Gagne : **Rayon de dévastation.** (1 utilisation, Ligne 10×2, zone) d66, gain d''1 Blessure."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Dravok, tyran omnivoyant' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Azriel, seigneur de la douleur et des flammes', 'Monstres légendaires · Énorme', 'Énorme balor légendaire, la cruauté incarnée.', '["Monstres légendaires","Légendaire","Niv. 14"]', 'GM''s Guide', NULL, '{"level":"14","size":"huge","minion":false,"legendary":true,"hp":120,"hpPerHero":true,"armor":null,"speed":null,"saves":"TOUTES+","abilities":[{"name":"DOULEUR !","text":"TOUS les dés primaires lancés contre Azriel font un critique sur 1 de moins que le maximum. En cas de critique, l''attaquant subit les dégâts explosifs à la place d''Azriel."}],"attacks":[{"name":"Fouet crépitant","dice":"2d12","bonus":10,"noCrit":false,"text":"Déplacement de 6. (Allonge 6) Attire la cible adjacente à Azriel."},{"name":"Épée funeste","dice":"2d12","bonus":20,"noCrit":false,"text":"(Allonge 2, zone)."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, choisissez 1 option (alterner recommandé) : Fouet crépitant ou Épée funeste."},{"title":"En sang","text":"Gagne : **Vents déchirants.** (Allonge 12, zone) Jet de sauvegarde de FOR DD 17 ou Déchiré : subit 2 dégâts par case parcourue (les soins y mettent fin). Azriel peut utiliser Fouet crépitant deux fois par tour."},{"title":"Baroud d''honneur : OUI, ENCORE PLUS DE DOULEUR !","text":"Azriel regagne 50 PV par héros, et CHAQUE coup contre lui est un critique."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Azriel, seigneur de la douleur et des flammes' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Ailesombre le Cruel', 'Monstres légendaires · Énorme', 'Énorme dragon de pourriture légendaire.', '["Monstres légendaires","Légendaire","Niv. 15"]', 'GM''s Guide', NULL, '{"level":"15","size":"huge","minion":false,"legendary":true,"hp":100,"hpPerHero":true,"armor":"heavy","speed":null,"saves":"TOUTES++","abilities":[{"name":"Aura de putréfaction","text":"(Allonge 6) Les ennemis subissent 5 dégâts nécrotiques à la fin de leurs tours."},{"name":"Sensibilité à la lumière","text":"Les dégâts radiants suppriment Aura de putréfaction jusqu''à la fin du tour du héros suivant."},{"name":"Don de la cruauté","text":"Les soins sont réduits de moitié et la cible est vulnérable aux dégâts nécrotiques. Les soins y mettent fin."}],"attacks":[{"name":"Griffes","dice":"2d10","bonus":10,"noCrit":false,"text":"Déplacement de 6, puis (Allonge 2). Si dégâts, Don de la cruauté."},{"name":"Morsure","dice":"2d20","bonus":10,"noCrit":false,"text":"(Allonge 2) Dégâts nécrotiques."},{"name":"Queue","dice":"1d10","bonus":10,"noCrit":false,"text":"(Cône 4, zone) Repoussé d''un nombre de cases égal au dé primaire."},{"name":"Souffle putride","dice":"8d10","bonus":0,"noCrit":true,"text":"En sang uniquement. (1 utilisation) Vole de 10, puis (Cône 8, zone) jet de sauvegarde de DEX DD 17 ou dégâts nécrotiques, moitié en cas de réussite."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, choisissez une option : Griffes, Morsure ou Queue."},{"title":"En sang","text":"Gagne : **Souffle putride** (1 utilisation). Vole de 10, puis (Cône 8, zone) jet de sauvegarde de DEX DD 17 ou 8d10 dégâts nécrotiques, moitié en cas de réussite."},{"title":"Baroud d''honneur","text":"Ailesombre regagne 30 PV par héros, Sensibilité à la lumière prend fin, et les dégâts et l''Allonge d''Aura de putréfaction sont doublés."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Ailesombre le Cruel' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Alaric Draegoth, le Comte écarlate', 'Monstres légendaires · Moyenne', 'Seigneur vampire légendaire.', '["Monstres légendaires","Légendaire","Niv. 16"]', 'GM''s Guide', NULL, '{"level":"16","size":"medium","minion":false,"legendary":true,"hp":90,"hpPerHero":true,"armor":null,"speed":null,"saves":"TOUTES++","abilities":[{"name":"Cape sanguine","text":"La 1re fois que vous êtes attaqué à chaque tour, infligez 1d10 et réduisez le dé primaire de ce montant."},{"name":"Mépris du soleil","text":"Vulnérable au radiant. Après avoir subi des dégâts radiants, utilise Envoûtement en réaction ; la cible lance avec désavantage."},{"name":"Envoûtement","text":"(Si aucune créature n''est envoûtée) Envoûte une cible sur un jet de sauvegarde de VOL DD 18 raté (avec désavantage si elle est en sang)."},{"name":"Envoûté","text":"Étourdi. Ne peut pas se défendre ni laisser quiconque s''interposer pour lui. Les dégâts y mettent fin."}],"attacks":[{"name":"Croc d''ébène","dice":"1d10","bonus":10,"noCrit":false,"text":"La cible est considérée en sang pendant 1 round. Vole de 8 avant ou après."},{"name":"Appel et festin","dice":"1d10","bonus":30,"noCrit":false,"text":"Amène une créature envoûtée adjacente à vous et mordez-la : dégâts et 1 Blessure."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, invoque 1 sbire chauve-souris de sang (d10) à 8 cases ou moins, puis choisissez 1 option (alterner recommandé) : Croc d''ébène, Envoûtement ou Appel et festin."},{"title":"En sang : Forme de brume","text":"N''est plus vulnérable au radiant, gagne : **Leurre de chauve-souris** (1/round). Chaque fois qu''Alaric devrait subir des dégâts, il échange d''abord sa place avec un sbire chauve-souris."},{"title":"Baroud d''honneur","text":"Regagne 25 PV par héros. Cape sanguine, attaques et chauves-souris lancent des d20 au lieu des d10."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Alaric Draegoth, le Comte écarlate' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Caerys, l''Étoile creuse', 'Monstres légendaires · Moyenne', 'Cataclysme légendaire de fin du monde. « Celle qui est notre désir et notre fin. »', '["Monstres légendaires","Légendaire","Niv. 20"]', 'GM''s Guide', NULL, '{"level":"20","size":"medium","minion":false,"legendary":true,"hp":125,"hpPerHero":true,"armor":"heavy","speed":null,"saves":"TOUTES+++","abilities":[{"name":"Ravages du temps","text":"Au début de chaque round, les ennemis subissent 1 Blessure."},{"name":"Sillage","text":"3/rencontre, quand elle devrait subir un effet négatif, elle peut échanger sa place avec une créature de son choix, qui en devient la cible à la place. Tous les héros récupèrent 1 Blessure."},{"name":"Entrevoir ta fin","text":"Jet de sauvegarde de VOL DD 20 ou CONDAMNÉ : la concentration prend fin, le prochain jet de dégâts contre vous est maximisé."}],"attacks":[{"name":"Trou de ver","dice":"3d20","bonus":0,"noCrit":false,"text":"Se téléporte de 12. À une créature adjacente à son point de départ ou d''arrivée."},{"name":"Immensité","dice":"3d20","bonus":0,"noCrit":true,"text":"(Allonge 12) À terre sur un jet de sauvegarde de FOR DD 20 raté (désavantage si à Allonge 4). Moitié en cas de réussite."},{"name":"Tempête de plasma","dice":"4d20","bonus":0,"noCrit":true,"text":"(Allonge 6, zone) Jet de sauvegarde de DEX DD 20 ou 2d20 dégâts de foudre et 2d20 dégâts de feu. Moitié en cas de réussite."},{"name":"Singularité","dice":"2d20","bonus":40,"noCrit":false,"text":"(Allonge 2) Dégâts contondants."},{"name":"Désir et fin","dice":"2d20","bonus":20,"noCrit":true,"text":"(Allonge 12) Jet de sauvegarde d''INT DD 20 ou dégâts, et choisissez un allié qui subit les mêmes dégâts. Moitié en cas de réussite."}],"sections":[{"title":"Actions","text":"Après le tour de chaque héros, choisissez 1 action pas encore choisie (on remet à zéro quand toutes l''ont été) : Trou de ver, Immensité, Entrevoir ta fin, Tempête de plasma, Singularité, Désir et fin."},{"title":"En sang","text":"**Maîtrise gravitationnelle.** (Allonge 16) Déplace TOUS les objets et créatures n''importe où dans la zone.\n**Lentille gravitationnelle.** Le héros qui a le plus de PV est marqué par Caerys. Elle subit la moitié des dégâts de toutes sources et sa marque subit l''autre moitié, jusqu''à ce que la marque tombe à 0 PV."},{"title":"Baroud d''honneur","text":"Perd son armure lourde. Utilise de nouveau Maîtrise gravitationnelle, puis Caerys regagne 60 PV par héros et choisit deux fois à chaque tour. Si elle est encore en vie après 1 round : **Retour dans le temps** : elle revient à ses PV maximum."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Caerys, l''Étoile creuse' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Krogg, roi gobelin', 'Aventures · Moyenne', 'Gobelours en colère légendaire (Les Gobelins de la Falaise de cristal, chapitre 2). Fort, rusé (plus malin que la moyenne des gobelins). Porte une couronne de ferraille. Manie le Broie-trappe, un marteau de guerre avec un piège à ours au bout.', '["Aventures","Légendaire","Niv. 2"]', 'GM''s Guide', NULL, '{"level":"2","size":"medium","minion":false,"legendary":true,"hp":28,"hpPerHero":true,"armor":null,"speed":null,"saves":"FOR+, DEX+","abilities":[],"attacks":[{"name":"Broie-trappe","dice":"2d6","bonus":0,"noCrit":false,"text":"Déplacement de 6. Agrippé (évasion DD 10). Ou :"},{"name":"Fracasse-crânes","dice":"2d6","bonus":0,"noCrit":false,"text":"Déplacement de 6. Projette une créature agrippée contre une autre créature. Les deux subissent les dégâts, ce qui met fin à l''agrippement."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, choisissez une option : Broie-trappe ou Fracasse-crânes."},{"title":"En sang : Enragé","text":"Les dégâts de Krogg passent aux d8."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Krogg, roi gobelin' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Dionée géante', 'Aventures · Énorme', 'Le Repaire de Pouce-Vert (chapitre 3), salle de la dionée. PV par héros.', '["Aventures","Niv. 3"]', 'GM''s Guide', NULL, '{"level":"3","size":"huge","minion":false,"legendary":false,"hp":20,"hpPerHero":true,"armor":null,"speed":null,"saves":null,"abilities":[{"name":"Plante vengeresse","text":"Agit aussi chaque fois qu''une Pousse meurt."},{"name":"Choisissez 1","text":"À son tour, choisissez 1 option : Enlacer, Ramener ou Morsure."},{"name":"Ramener","text":"(si elle agrippe) Attire la cible adjacente, puis Morsure."}],"attacks":[{"name":"Enlacer","dice":"1d6","bonus":2,"noCrit":false,"text":"(Allonge 12, jusqu''à 2 cibles différentes) Agrippé (évasion DD 12, ou tout dégât de feu ou tranchant)."},{"name":"Morsure","dice":"1d6","bonus":15,"noCrit":false,"text":"(Allonge 3)."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Dionée géante' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Pinky', 'Aventures · Petite', 'Le Repaire de Pouce-Vert (chapitre 3). Gobelin rose, frêle et terriblement anxieux, assistant de Pouce-Vert.', '["Aventures","Niv. 2"]', 'GM''s Guide', NULL, '{"level":"2","size":"small","minion":false,"legendary":false,"hp":18,"armor":null,"speed":null,"saves":null,"abilities":[{"name":"Panique","text":"Les attaques contre vous ont le désavantage."},{"name":"Protégez-moi !","text":"Ordonne à un Brise-racines d''attaquer."},{"name":"Fuite","text":"(Réaction, quand il est en sang) Utilise sa Cape de forme-vent mineure pour devenir invisible et s''enfuir."}],"attacks":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Pinky' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Pouce-Vert, liche naissante', 'Aventures · Moyenne', 'Magicien botaniste légendaire (Le Repaire de Pouce-Vert, chapitre 3). Sorcier grenouillin.', '["Aventures","Légendaire","Niv. 3"]', 'GM''s Guide', NULL, '{"level":"3","size":"medium","minion":false,"legendary":true,"hp":40,"hpPerHero":true,"armor":null,"speed":null,"saves":"INT+, VOL+","abilities":[{"name":"Ronçomancie","text":"Déplacement de 4. Invoque 1 sbire plante par héros (chacun se déplace et attaque pour 1d4 dégâts à la fin de chaque round)."}],"attacks":[{"name":"Tir d''épines","dice":"2d4","bonus":8,"noCrit":false,"text":"Déplacement de 4. (Portée 8)."},{"name":"Racines épineuses","dice":"2d4","bonus":0,"noCrit":true,"text":"En sang uniquement. Tous les héros : jet de sauvegarde de DEX DD 11 ou dégâts et immobilisé ; moitié des dégâts en cas de réussite."}],"sections":[{"title":"Légendaire","text":"Après le tour de chaque héros, choisissez une option (alterner recommandé) : Ronçomancie ou Tir d''épines."},{"title":"En sang : Racines épineuses","text":"Tous les héros font un jet de sauvegarde de DEX DD 11 ou subissent 2d4 dégâts et sont immobilisés ; moitié des dégâts en cas de réussite (évasion : FOR ou DEX DD 11, ou tout dégât tranchant ou radiant)."},{"title":"Baroud d''honneur : Peau d''écorce","text":"Pouce-Vert regagne 10 PV par héros et une armure lourde. Être touché dégrade l''armure (lourde » moyenne » aucune). Il peut aussi choisir deux fois par tour."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Pouce-Vert, liche naissante' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'GM''s Guide');
